<section class="evaluation-student-header"><span><?=e($area)?> · <?=e($student['registration_number'])?></span><h2><?=e(evaluation_student_name($student))?></h2><p><?=e($test['title'])?> · 10 critérios · máximo de 100 pontos</p></section>
<section class="evaluation-scoring-board" aria-live="polite"><div><span>RESPONDIDOS</span><strong id="answeredCount">0/10</strong></div><div><span>PONTOS</span><strong id="pointsCount">0/100</strong></div><div><span>NOTA PARCIAL</span><strong id="partialGrade">—</strong></div></section>
<div class="evaluation-score-legend"><b>REGULAR <em>5</em><small>pontos</small></b><b>BOM <em>8</em><small>pontos</small></b><b>ÓTIMO <em>9</em><small>pontos</small></b><b>EXCELENTE <em>10</em><small>pontos</small></b></div>
<form method="post" class="evaluation-form" id="evaluationForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="test_id" value="<?=$testId?>"><input type="hidden" name="area" value="<?=e($area)?>"><input type="hidden" name="student_id" value="<?=$studentId?>"><?php foreach($criteria as $i=>$c):?><fieldset class="evaluation-question"><legend><b><?=($i+1)?>.</b> <?=e($c['criterion'])?></legend><div class="rating-options"><?php foreach(evaluation_rating_options() as $points=>$label):?><label class="rating-<?=$points?>"><input type="radio" name="score[<?=$c['id']?>]" value="<?=$points?>" <?=($existingScores[(int)$c['id']]??0)===$points?'checked':''?> required><span><strong><?=e($label)?></strong><small><?=$points?> PONTOS</small></span></label><?php endforeach;?></div></fieldset><?php endforeach;?><div class="evaluation-submit-bar"><a class="instr-secondary" href="avaliacao_alunos.php?test_id=<?=$testId?>&area=<?=urlencode($area)?>">CANCELAR</a><button class="instr-primary">SALVAR AVALIAÇÃO DO ALUNO</button></div></form>
<script>
(()=>{const form=document.getElementById('evaluationForm'),answered=document.getElementById('answeredCount'),points=document.getElementById('pointsCount'),grade=document.getElementById('partialGrade');function update(){const checked=[...form.querySelectorAll('input[type=radio]:checked')],sum=checked.reduce((n,x)=>n+Number(x.value||0),0);answered.textContent=checked.length+'/10';points.textContent=sum+'/100';grade.textContent=checked.length?((sum/checked.length).toFixed(1).replace('.',',')+'/10'):'—';}form.addEventListener('change',update);update();})();
</script>
